<script setup lang="ts">
import {computed,onMounted,ref} from 'vue'
import RunnerSettingsNav from '@/components/RunnerSettingsNav.vue'
import {runnerProfiles,type RunnerProfile,type ProfileConfig,type ToolCatalog,type ModelEntry} from '@/api/runnerProfiles'
import {runnerConnections,type ConnectionList} from '@/api/runnerConnections'
import {runnerBudgets,type BudgetList} from '@/api/runnerBudgets'
import {skillsApi,type Skill} from '@/api/skills'
const profiles=ref<RunnerProfile[]>([]),skills=ref<Skill[]>([]),connections=ref<ConnectionList|null>(null),budgets=ref<BudgetList|null>(null),tools=ref<ToolCatalog|null>(null),models=ref<ModelEntry[]>([])
const notice=ref(''),error=ref(''),busy=ref(false),editing=ref<RunnerProfile|null>(null),name=ref(''),enabled=ref(true),skillId=ref('chat'),connectionId=ref(''),budgetId=ref('standard'),role=ref(''),grants=ref<string[]>([]),preview=ref('')
const skill=computed(()=>skills.value.find(s=>s.id===skillId.value))
const allowed=computed(()=>skill.value?.default_version?.manifest.requested_tools||[])
async function load(){const [p,s,c,b,t,m]=await Promise.all([runnerProfiles.list(),skillsApi.list(),runnerConnections.list(),runnerBudgets.list(),runnerProfiles.tools(),runnerProfiles.models()]);profiles.value=p.profiles;skills.value=s.skills.filter(s=>s.status==='enabled'&&!['paper_guide','paper_import','frontier_monitor'].includes(s.id));connections.value=c;budgets.value=b;tools.value=t;models.value=m.models}
onMounted(async()=>{try{await load()}catch(e){error.value=String(e)}})
function edit(p:RunnerProfile|null){editing.value=p;name.value=p?.name||'';enabled.value=p?.enabled??true;skillId.value=p?.config.skill_id||'chat';connectionId.value=p?.config.connection?.id||'';budgetId.value=p?.config.budget.id||'standard';role.value=p?.config.role_prompt||'';grants.value=[...(p?.config.tools||[])];preview.value='';error.value=''}
function config():ProfileConfig{const s=skill.value?.default_version,b=budgets.value?.budgets.find(b=>b.id===budgetId.value),c=connections.value?.connections.find(c=>c.id===connectionId.value);if(!s||!b)throw Error('请选择有效的 Skill 版本与额度');if(!c&&!connections.value?.legacy_available)throw Error('请选择自己的模型连接');return {skill_id:skillId.value,skill_version_id:s.id,connection:c?{id:c.id,revision:c.revision}:null,budget:{id:b.id,revision:b.revision},role_prompt:role.value,tools:grants.value}}
async function submit(check=false){busy.value=true;error.value='';try{const cfg=config();if(check)preview.value=JSON.stringify(await runnerProfiles.preview(cfg),null,2);else{await runnerProfiles.save({name:name.value,enabled:enabled.value,config:cfg,...(editing.value?{expected_revision:editing.value.revision}:{})},editing.value?.id);await load();edit(null);notice.value='方案已保存；已有会话保持原绑定。'}}catch(e){error.value=String(e)}finally{busy.value=false}}
</script>
<template><main class="config-page"><RunnerSettingsNav/><h1>执行方案、模型与 MCP</h1><p>将 Skill、模型连接、任务额度、研究角色和工具权限保存为方案。会话首次执行后固定绑定；配置修订后请新建会话。校验与保存不会调用模型。</p><p v-if="error" role="alert">{{ error }}</p><p v-if="notice" role="status">{{ notice }}</p>
<section><h2>执行方案</h2><div class="profile-list"><button @click="edit(null)">＋ 新建方案</button><button v-for="p in profiles" :key="p.id" @click="edit(p)">{{ p.name }} · v{{ p.revision }} · {{ p.enabled?'启用':'停用' }}</button></div>
<form @submit.prevent="submit()"><h3>{{ editing?'修改方案':'新建方案' }}</h3><label>名称<input v-model="name" maxlength="80" required/></label><label>Skill<select v-model="skillId" @change="grants=[];preview='' "><option v-for="s in skills" :key="s.id" :value="s.id">{{ s.name }} · {{ s.default_version?.version }}</option></select></label><label>模型连接<select v-model="connectionId"><option v-if="!connections?.legacy_available" disabled value="">请选择模型连接</option><option v-if="connections?.legacy_available" value="">部署环境连接（固定绑定）</option><option v-for="c in connections?.connections||[]" :key="c.id" :value="c.id" :disabled="!c.enabled">{{ c.name }} · {{ c.config.model }} · v{{ c.revision }}</option></select></label><label>额度<select v-model="budgetId"><option v-for="b in budgets?.budgets||[]" :key="b.id" :value="b.id">{{ b.name }} · v{{ b.revision }}</option></select></label><label>补充研究角色<textarea v-model="role" maxlength="6000" rows="4"/></label><fieldset><legend>内置 MCP 工具（只能缩小 Skill 权限）</legend><label v-for="t in allowed" :key="t" class="check"><input v-model="grants" type="checkbox" :value="t"/>{{ t }}</label><p v-if="!allowed.length">此 Skill 无工具权限。</p></fieldset><label class="check"><input v-model="enabled" type="checkbox"/>启用方案</label><p v-if="editing">保存会创建新修订，并绑定当前的 Skill、连接和额度版本。已有会话不会静默切换。</p><div class="actions"><button type="button" :disabled="busy" @click="submit(true)">校验配置</button><button :disabled="busy||!name.trim()">保存方案</button></div><pre v-if="preview">{{ preview }}</pre></form></section>
<section><h2>模型目录</h2><p>来自当前账号的模型连接；视觉与上下文是配置声明，尚不代表实际验证。新增模型请进入“模型连接”。</p><ul><li v-for="m in models" :key="m.connection_id">{{ m.connection_name }} · {{ m.model }} · {{ m.context_window.toLocaleString() }} 上下文 · {{ m.vision }} · {{ m.enabled?'启用':'停用' }}</li></ul><p v-if="!models.length">尚无自定义模型连接。</p></section><section><h2>MCP 工具目录</h2><p>当前管理 Firework 内置工具。实际授权还取决于 Skill、执行方案及当前任务绑定。任意外部 MCP 服务尚未开放。</p><div class="tool-grid" v-for="server in tools?.servers||[]" :key="server.id"><h3>{{ server.id }} · {{ server.transport }}</h3><div v-for="t in server.tools" :key="t.name"><code>{{ t.name }}</code><span>{{ t.effect==='read'?'只读':'受限写入' }}</span></div></div></section></main></template>
<style scoped>.config-page{max-width:1080px;margin:auto;padding:32px 24px;line-height:1.65}.config-page section{border:1px solid var(--border,#ddd);padding:22px;border-radius:12px;margin:22px 0}.config-page label{display:grid;gap:6px;margin:14px 0}.config-page input,.config-page select,.config-page textarea{padding:9px;max-width:100%;min-width:0}.config-page .check{display:flex;align-items:center;gap:8px}.profile-list,.actions{display:flex;flex-wrap:wrap;gap:10px}button{padding:8px 14px}.tool-grid>div{display:flex;justify-content:space-between;gap:16px;border-bottom:1px solid var(--border,#ddd);padding:8px;overflow-wrap:anywhere}pre{overflow:auto;max-height:320px;white-space:pre-wrap;font-size:12px}</style>
